# ─── Module Registry & Lazy Loader ───────────────────────────────────────────

class LazyModule:
    """Lazy-loading wrapper that defers import until first access."""
    __slots__ = ('_name', '_module', '_loaded', '_ref')

    def __init__(self, name: str):
        self._name = name
        self._module = None
        self._loaded = False
        self._ref = None

    def load(self) -> Any:
        if not self._loaded:
            try:
                self._module = importlib.import_module(self._name)
            except ImportError:
                self._module = None
            self._loaded = True
        return self._module

    def unload(self) -> None:
        """Release module reference to free memory."""
        self._module = None
        self._loaded = False
        gc.collect()

    @property
    def is_loaded(self) -> bool:
        return self._loaded and self._module is not None


class ModuleRegistry:
    """Central registry for lazy-loaded dashboard sub-modules."""

    def __init__(self):
        self._modules: Dict[str, LazyModule] = {}
        self._access_times: Dict[str, float] = {}
        self._lock = threading.Lock()
        self._unload_after = 300.0  # 5 min idle → unload
        self._cleanup_thread: Optional[threading.Thread] = None
        self._running = False

    def register(self, name: str, import_path: str) -> LazyModule:
        lm = LazyModule(import_path)
        self._modules[name] = lm
        return lm

    def get(self, name: str) -> Any:
        with self._lock:
            lm = self._modules.get(name)
            if lm is None:
                raise KeyError(f"Module '{name}' not registered")
            self._access_times[name] = time.time()
            return lm.load()

    def start_cleanup(self):
        self._running = True
        self._cleanup_thread = threading.Thread(
            target=self._cleanup_loop, daemon=True, name="module-cleanup"
        )
        self._cleanup_thread.start()

    def stop_cleanup(self):
        self._running = False

    def _cleanup_loop(self):
        while self._running:
            time.sleep(60)
            now = time.time()
            with self._lock:
                for name, lm in list(self._modules.items()):
                    last = self._access_times.get(name, 0)
                    if lm.is_loaded and (now - last) > self._unload_after:
                        lm.unload()

    def memory_report(self) -> Dict[str, Dict]:
        report = {}
        for name, lm in self._modules.items():
            report[name] = {
                "loaded": lm.is_loaded,
                "last_access": self._access_times.get(name, None),
            }
        return report


# ─── Dashboard State Cache ───────────────────────────────────────────────────

class DashboardState:
    """
    Centralized in-memory state replacing scattered globals.
    Uses LRU eviction to bound memory usage.
    """

    def __init__(self, max_entries: int = 1000):
        self._cache: OrderedDict[str, Any] = OrderedDict()
        self._max = max_entries
        self._lock = threading.RLock()
        self._stats = defaultdict(int)

    def get(self, key: str, default=None) -> Any:
        with self._lock:
            if key in self._cache:
                self._cache.move_to_end(key)
                self._stats["hits"] += 1
                return self._cache[key]
            self._stats["misses"] += 1
            return default

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self._lock:
            if key in self._cache:
                self._cache.move_to_end(key)
            self._cache[key] = {
                "value": value,
                "expires": time.time() + ttl if ttl else None,
            }
            while len(self._cache) > self._max:
                self._cache.popitem(last=False)
            self._stats["sets"] += 1

    def invalidate(self, key: str) -> None:
        with self._lock:
            self._cache.pop(key, None)
            self._stats["invalidations"] += 1

    def clear(self) -> None:
        with self._lock:
            self._cache.clear()

    def stats(self) -> Dict[str, int]:
        with self._lock:
            return dict(self._stats)

    def cleanup_expired(self) -> int:
        now = time.time()
        removed = 0
        with self._lock:
            expired = [
                k for k, v in self._cache.items()
                if v.get("expires") and v["expires"] < now
            ]
            for k in expired:
                del self._cache[k]
                removed += 1
        return removed


# ─── Route Registry ──────────────────────────────────────────────────────────

@dataclass
class Route:
    path: str
    method: str
    handler_name: str
    module_name: str
    description: str = ""


class DashboardRouter:
    """Route registry with lazy handler resolution from sub-modules."""

    def __init__(self, registry: ModuleRegistry):
        self._routes: Dict[Tuple[str, str], Route] = {}
        self._registry = registry

    def add(self, path: str, method: str, module_name: str,
            handler_name: str, description: str = "") -> None:
        key = (method.upper(), path)
        self._routes[key] = Route(
            path=path, method=method.upper(),
            handler_name=handler_name,
            module_name=module_name,
            description=description,
        )

    def resolve(self, method: str, path: str) -> Optional[Tuple[Route, Callable]]:
        key = (method.upper(), path)
        route = self._routes.get(key)
        if route is None:
            # Try prefix match for parameterized routes
            for (m, p), r in self._routes.items():
                if m == method.upper() and path.startswith(p.rstrip("/")):
                    route = r
                    break
        if route is None:
            return None
        module = self._registry.get(route.module_name)
        if module is None:
            return None
        handler = getattr(module, route.handler_name, None)
        if handler is None:
            return None
        return route, handler

    def list_routes(self) -> List[Dict]:
        return [
            {
                "method": r.method,
                "path": r.path,
                "module": r.module_name,
                "handler": r.handler_name,
                "description": r.description,
            }
            for r in self._routes.values()
        ]


