def _create_websocket_module():
    """Create WebSocket/SSE sub-module for event-based updates (replaces polling)."""
    import types
    mod = types.ModuleType("dashboard_ws")

    class EventBroadcaster:
        """Broadcasts pg_notify events to connected SSE clients, replacing 3s polling."""

        def __init__(self):
            self._clients: List[Any] = []
            self._lock = threading.Lock()
            self._event_queue: List[dict] = []
            self._max_queue = 100

        def add_client(self, client) -> None:
            with self._lock:
                self._clients.append(client)

        def remove_client(self, client) -> None:
            with self._lock:
                if client in self._clients:
                    self._clients.remove(client)

        def broadcast(self, event: dict) -> None:
            with self._lock:
                self._event_queue.append(event)
                if len(self._event_queue) > self._max_queue:
                    self._event_queue = self._event_queue[-self._max_queue:]
                clients = list(self._clients)
            for c in clients:
                try:
                    c.send_event(event)
                except Exception:
                    self.remove_client(c)

        def get_recent_events(self, since: float = 0) -> List[dict]:
            with self._lock:
                return [e for e in self._event_queue if e.get("ts", 0) > since]

        @property
        def client_count(self) -> int:
            with self._lock:
                return len(self._clients)

    mod.EventBroadcaster = EventBroadcaster
    return mod


# ─── HTTP Request Handler ────────────────────────────────────────────────────

class DashboardRequestHandler(BaseHTTPRequestHandler):
    """HTTP handler with lazy route resolution."""

    # Class-level shared state (set by server)
    router: Optional[DashboardRouter] = None
    state: Optional[DashboardState] = None
    registry: Optional[ModuleRegistry] = None
    broadcaster: Optional[Any] = None
    start_time: float = 0

    def log_message(self, fmt, *args):
        pass  # Suppress default logging

    def _send_json(self, data: dict, status: int = 200) -> None:
        body = json.dumps(data, default=str).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_html(self, html: bytes, status: int = 200) -> None:
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(html)))
        self.end_headers()
        self.wfile.write(html)

    def _send_sse(self) -> None:
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-cache")
        self.send_header("Connection", "keep-alive")
        self.end_headers()

        # Send initial events
        recent = self.broadcaster.get_recent_events() if self.broadcaster else []
        for evt in recent:
            data = f"data: {json.dumps(evt)}\n\n"
            self.wfile.write(data.encode("utf-8"))
            self.wfile.flush()

        # Register as SSE client
        class SSEClient:
            def __init__(self, wfile):
                self.wfile = wfile

            def send_event(self, event: dict) -> None:
                data = f"data: {json.dumps(event)}\n\n"
                self.wfile.write(data.encode("utf-8"))
                self.wfile.flush()

        client = SSEClient(self.wfile)
        if self.broadcaster:
            self.broadcaster.add_client(client)

        # Keep connection open
        try:
            while True:
                time.sleep(15)
                self.wfile.write(b": ping\n\n")
                self.wfile.flush()
        except (BrokenPipeError, ConnectionResetError):
            pass
        finally:
            if self.broadcaster:
                self.broadcaster.remove_client(client)

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path

        # SSE endpoint
        if path == "/events":
            self._send_sse()
            return

        resolved = self.router.resolve("GET", path)
        if resolved is None:
            self._send_json({"error": "not found", "path": path}, 404)
            return

        route, handler = resolved

        try:
            if route.module_name == "dashboard_routes":
                # Build dashboard context
                context = {
                    "active_peers": self.state.get("active_peers", 0),
                    "total_messages": self.state.get("total_messages", 0),
                    "uptime": self._format_uptime(),
                    "state": self.state.get("mesh_state", "healthy"),
                    "modules": self.registry.memory_report(),
                    "routes": self.router.list_routes(),
                    "cache_stats": self.state.stats(),
                }
                html = handler(context)
                self._send_html(html)
            elif route.module_name == "dashboard_api":
                if path == "/api/status":
                    result = handler(self.state, self.registry)
                elif path == "/api/routes":
                    result = handler(self.router)
                elif path == "/api/modules":
                    result = handler(self.registry)
                elif path == "/api/cache":
                    result = handler(self.state)
                elif path == "/api/health":
                    result = handler()
                else:
                    result = handler()
                self._send_json(result)
            else:
                self._send_json({"error": "unknown module"}, 500)
        except Exception as e:
            self._send_json({"error": str(e), "type": type(e).__name__}, 500)

    def do_POST(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path

        content_len = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(content_len) if content_len > 0 else b""

        resolved = self.router.resolve("POST", path)
        if resolved is None:
            self._send_json({"error": "not found", "path": path}, 404)
            return

        route, handler = resolved

        try:
            payload = json.loads(body) if body else {}
            if path == "/api/cache/clear":
                result = handler(self.state)
            else:
                result = handler(payload)
            self._send_json(result)
        except Exception as e:
            self._send_json({"error": str(e)}, 500)

    def _format_uptime(self) -> str:
        elapsed = time.time() - self.start_time
        hours = int(elapsed // 3600)
        mins = int((elapsed % 3600) // 60)
        secs = int(elapsed % 60)
        return f"{hours}h {mins}m {secs}s"


# ─── Dashboard Server ────────────────────────────────────────────────────────

class DashboardServer:
    """
    Main dashboard server with modular architecture.
    Replaces the monolithic 4916-line dashboard.py.
    """

    def __init__(self, host: str = "0.0.0.0", port: int = 8080):
        self.host = host
        self.port = port
        self.start_time = time.time()

        # Core components
        self.state = DashboardState(max_entries=500)
        self.registry = ModuleRegistry()
        self.router = DashboardRouter(self.registry)

        # Register sub-modules as lazy modules
        self._routes_mod = self.registry.register("dashboard_routes", "dashboard_routes")
        self._api_mod = self.registry.register("dashboard_api", "dashboard_api")
        self._ws_mod = self.registry.register("dashboard_ws", "dashboard_ws")

        # Inject inline modules into sys.modules so importlib finds them
        sys.modules["dashboard_routes"] = _create_routes_module()
        sys.modules["dashboard_api"] = _create_api_module()
        sys.modules["dashboard_ws"] = _create_websocket_module()

        # Register routes
        self._register_routes()

        # Event broadcaster (replaces reply-polling)
        ws_mod = self.registry.get("dashboard_ws")
        self.broadcaster = ws_mod.EventBroadcaster()

        # Simulated mesh state
        self.state.set("active_peers", 3)
        self.state.set("total_messages", 0)
        self.state.set("mesh_state", "healthy")

        # Background threads
        self._sim_thread: Optional[threading.Thread] = None
        self._running = False

    def _register_routes(self) -> None:
        """Register all dashboard routes with lazy handler resolution."""
        self.router.add("/", "GET", "dashboard_routes", "render_dashboard",
                        "Main dashboard page")
        self.router.add("/dashboard", "GET", "dashboard_routes", "render_dashboard",
                        "Dashboard alias")
        self.router.add("/api/status", "GET", "dashboard_api", "api_status",
                        "System status JSON")
        self.router.add("/api/routes", "GET", "dashboard_api", "api_routes",
                        "List registered routes")
        self.router.add("/api/modules", "GET", "dashboard_api", "api_modules",
                        "Module memory report")
        self.router.add("/api/cache", "GET", "dashboard_api", "api_cache_stats",
                        "Cache statistics")
        self.router.add("/api/cache/clear", "POST", "dashboard_api", "api_cache_clear",
                        "Clear cache")
        self.router.add("/api/health", "GET", "dashboard_api", "api_health",
                        "Health check")

    def _simulate_events(self) -> None:
        """Simulate pg_notify events for demonstration."""
        msg_count = 0
        while self._running:
            time.sleep(5)
            msg_count += 1
            self.state.set("total_messages", msg_count)
            event = {
                "type": "message",
                "ts": time.time(),
                "data": {"id": msg_count, "peer": f"peer_{msg_count % 3}"},
            }
            self.broadcaster.broadcast(event)

            # Periodic cache cleanup
            if msg_count % 6 == 0:
                removed = self.state.cleanup_expired()
                if removed:
                    self.broadcaster.broadcast({
                        "type": "cache_cleanup",
                        "ts": time.time(),
                        "removed": removed,
                    })

    def _create_handler_class(self):
        """Create a handler class with bound shared state."""
        server = self

        class BoundHandler(DashboardRequestHandler):
            router = server.router
            state = server.state
            registry = server.registry
            broadcaster = server.broadcaster
            start_time = server.start_time

        return BoundHandler

    def run(self) -> None:
        """Start the dashboard server."""
        self._running = True
        self.registry.start_cleanup()

        # Start event simulation
        self._sim_thread = threading.Thread(
            target=self._simulate_events, daemon=True, name="event-sim"
        )
        self._sim_thread.start()

        handler_class = self._create_handler_class()
        httpd = HTTPServer((self.host, self.port), handler_class)

        print(f"Dashboard running on http://{self.host}:{self.port}")
        print(f"  Modules registered: {list(self.registry._modules.keys())}")
        print(f"  Routes registered: {len(self.router._routes)}")
        print(f"  SSE endpoint: http://{self.host}:{self.port}/events")
        print(f"  Press Ctrl+C to stop")

        try:
            httpd.serve_forever()
        except KeyboardInterrupt:
            print("\nShutting down...")
        finally:
            self._running = False
            self.registry.stop_cleanup()
            httpd.server_close()


# ─── CLI Entry Point ─────────────────────────────────────────────────────────

def main():
    import argparse

    parser = argparse.ArgumentParser(
        description="A2A Mesh Modular Dashboard — refactored from monolithic dashboard.py"
    )
    parser.add_argument("--host", default="0.0.0.0", help="Bind host (default: 0.0.0.0)")
    parser.add_argument("--port", type=int, default=8080, help="Port (default: 8080)")
    parser.add_argument("--debug", action="store_true", help="Enable debug output")
    args = parser.parse_args()

    if args.debug:
        import logging
        logging.basicConfig(level=logging.DEBUG)

    server = DashboardServer(host=args.host, port=args.port)
    server.run()


if __name__ == "__main__":
    main()